le->published_at??'now')) ?>"></label><button class="studio-btn primary" type="submit">Salvar matéria</button></div></section><section class="studio-panel"><header class="studio-panel-header"><div><p class="studio-eyebrow">Organização</p><h2 class="studio-panel-title">Categoria</h2></div></header><div class="studio-panel-body"><label class="studio-field studio-label">Categoria *<select class="studio-select" name="category_id" required><option value="">Selecione</option><?php foreach($categories as $category): ?><option value="<?= $category->id ?>" <?= ($article->category_id??null)==$category->id?'selected':'' ?>><?= htmlspecialchars($category->title) ?></option><?php endforeach; ?></select></label></div></section><section class="studio-panel"><header class="studio-panel-header"><div><p class="studio-eyebrow">Destaque</p><h2 class="studio-panel-title">Imagem de capa</h2></div></header><div class="studio-panel-body studio-stack"><input type="hidden" id="support-library-cover" name="library_cover"><label class="studio-cover-upload"><input type="file" name="cover" accept="image/jpeg,image/png,image/webp"><span><ion-icon name="cloud-upload-outline"></ion-icon><strong>Enviar nova imagem</strong><small>Opcional</small></span></label><button class="studio-btn studio-media-pick" type="button" data-media-picker data-media-target="#support-library-cover" data-media-preview=".support-cover-preview"><ion-icon name="images-outline"></ion-icon>Escolher da biblioteca</button><img class="studio-preview support-cover-preview <?= empty($article->cover)?'is-empty':'' ?>" src="<?= !empty($article->cover)?image($article->cover,600):'' ?>" alt="Capa"></div></section><?php if($article): ?><section class="studio-panel studio-danger-zone"><div class="studio-panel-body"><p class="studio-eyebrow">Cuidado</p><button class="studio-btn danger" type="submit" name="action" value="delete" data-confirm-submit="Excluir esta matéria?">Excluir matéria</button></div></section><?php endif; ?></aside></div></form>
